package export_ohrats_rc_mesh_diagnostics_reports

import (
	witTypes "go.bytecodealliance.org/pkg/wit/types"
	"wit_component/ohrats_rc_diagnostics_query"
	"wit_component/ohrats_rc_diagnostics_types"
	"wit_component/ohrats_rc_mesh_diagnostics_authorization"
)

func Recent(peerId string, grantId string, limit uint32) witTypes.Result[[]ohrats_rc_diagnostics_types.Event, string] {
	if !ohrats_rc_mesh_diagnostics_authorization.Allowed(peerId, grantId) {
		return witTypes.Err[[]ohrats_rc_diagnostics_types.Event, string]("diagnostics grant is not authorized for this peer")
	}
	return ohrats_rc_diagnostics_query.Recent(limit)
}
